-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='view') }}

with
checked_pre_input as (
    select
        product_name,
        brand,
        category,
        currency,
        product_status,
        source_record_id,
        source_product_id,
        product_code,
        list_price,
        as_of_date,
        source_system
    from {{ ref("ecommerce__product__checked_pre") }}
),
step_02_schema_transform as (
    select
        product_name,
        product_status,
        product_code,
        cast(source_record_id as {{ dpf_type('string') }}) as product_record_id,
        cast(source_product_id as {{ dpf_type('string') }}) as product_source_id,
        cast(source_system as {{ dpf_type('string') }}) as product_source_system,
        cast(brand as {{ dpf_type('string') }}) as product_brand,
        cast(category as {{ dpf_type('string') }}) as product_category,
        cast(list_price as {{ dpf_decimal_type(12, 2) }}) as product_list_price,
        cast(currency as {{ dpf_type('string') }}) as product_currency,
        cast(as_of_date as {{ dpf_type('date') }}) as product_as_of_date
    from checked_pre_input
),
curation_records as (
    select
        product_name,
        product_status,
        product_code,
        product_record_id,
        product_source_id,
        product_source_system,
        product_brand,
        product_category,
        product_list_price,
        product_currency,
        product_as_of_date,
        product_record_id as resolution_record_key
    from step_02_schema_transform
),
curation_edges as (
    select
        resolution_record_key,
        1 as key_rank,
        'product_code' as key_name,
        'product_code:' || product_code as key_value
    from curation_records
    where product_code is not null
),
curation_labels_0 as (
    select distinct
        resolution_record_key,
        resolution_record_key as label
    from curation_edges
),
curation_values_1 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_0 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_1 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_1 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_values_2 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_1 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_2 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_2 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_components as (
    select
        resolution_record_key,
        label as component_id
    from curation_labels_2
),
curation_component_stats as (
    select
        component_id,
        count(*) as component_row_count
    from curation_components
    group by component_id
),
curation_component_keys as (
    select
        components.component_id,
        min(edges.key_rank) as best_key_rank
    from curation_components as components
    inner join curation_edges as edges
        on edges.resolution_record_key = components.resolution_record_key
    group by components.component_id
),
curation_resolved as (
    select
        records.product_name,
        records.product_status,
        records.product_code,
        records.product_record_id,
        records.product_source_id,
        records.product_source_system,
        records.product_brand,
        records.product_category,
        records.product_list_price,
        records.product_currency,
        records.product_as_of_date,
        records.resolution_record_key,
        coalesce(components.component_id, records.resolution_record_key) as resolution_entity_key,
        coalesce(stats.component_row_count, 1) as resolution_row_count,
        case
            when keys.best_key_rank = 1 then 'product_code'
        end as resolution_key_name,
        case
            when coalesce(stats.component_row_count, 1) > 1 then 'deterministic'
            else 'unresolved'
        end as resolution_tier,
        coalesce(stats.component_row_count, 1) = 1 as resolution_pending
    from curation_records as records
    left join curation_components as components
        on components.resolution_record_key = records.resolution_record_key
    left join curation_component_stats as stats
        on stats.component_id = components.component_id
    left join curation_component_keys as keys
        on keys.component_id = components.component_id
)

select
    product_name,
    product_status,
    product_code,
    product_record_id,
    product_source_id,
    product_source_system,
    product_brand,
    product_category,
    product_list_price,
    product_currency,
    product_as_of_date,
    resolution_record_key,
    resolution_entity_key,
    resolution_row_count,
    resolution_key_name,
    resolution_tier,
    resolution_pending
from curation_resolved
